/// The shared model-list dispatch for the settings flows and the cache
/// refresh: CodeMie endpoints list `/llm_models`, DIAL serves deployments
/// (recording the reported limits), Copilot runs the token-exchange
/// dialect (also recording the reported limits), everything else is an
/// OpenAI-compatible `/models` ([AgentCliConfig.modelsFetcher] override
/// included). Without this a DIAL/CodeMie pick dropped the user into
/// manual model entry. [onCopilotReport] receives the Copilot fetch
/// report (gh-1990) — the connect flow surfaces the empty-answer reason.
Future<List<String>> _fetchProviderModelIds(
  String providerName,
  String baseUrl,
  String key, {
  void Function(ModelsFetchReport report)? onCopilotReport,
}) async {
  if (baseUrl.contains('/code-assistant-api/')) {
    return fetchCodeMieModels(
      baseUrl,
      key,
      // The active entry's project scopes the list (issue #1941) — only
      // when the fetch targets the endpoint the live model serves (the
      // shared sameEndpoint rule, so a trailing-slash twin still
      // matches), and a setup-time fetch of ANOTHER endpoint stays
      // unscoped.
      project: sameEndpoint(_agent.state.model.baseUrl, baseUrl)
          ? _agent.state.model.codeMieProject
          : null,
      client: modelFetchClient(providerName),
    );
  }
  if (providerName == 'dial') {
    return _fetchDialModelsAndFeatures(baseUrl, apiKey: [REDACTED:Sensitive-Value]);
  }
  // Identity by kind, not a name literal (issue #772): the branch fires
  // for the catalog name AND the adapter kind.
  if (resolveCliProviderSpec(providerName)?.kind == 'chatgpt-codex') {
    final (ids, _, _) = await fetchModelsForEndpoint(
      baseUrl,
      apiKey: [REDACTED:Sensitive-Value],
      provider: 'chatgpt',
      client: modelFetchClient('chatgpt'),
    );
    return ids;
  }
  if (providerName == 'copilot') {
    final (ids, report) = await _fetchCopilotModelsAndLimits(
      baseUrl,
      apiKey: [REDACTED:Sensitive-Value],
    );
    onCopilotReport?.call(report);
    return ids;
  }
  final override = config.modelsFetcher;
  if (override != null) return override(baseUrl, apiKey: [REDACTED:Sensitive-Value]);
  return _fetchOpenAiCompatibleModels(
    baseUrl,
    apiKey: [REDACTED:Sensitive-Value],
    client: modelFetchClient(providerName),
  );
